def check(args, result, expected):
    n, pre = args
    if not expected:
        return result == []
    if not isinstance(result, list) or sorted(result) != list(range(n)):
        return False
    pos = {c: i for i, c in enumerate(result)}
    return all(pos[b] < pos[a] for a, b in pre)

